import{_ as a,H as s,f as i,i as o}from"./chunks/framework.DLd0CbzH.js";const k=JSON.parse('{"title":"Production (Docker Compose)","description":"","frontmatter":{},"headers":[],"relativePath":"dev/docker/production.md","filePath":"dev/docker/production.md"}'),t={name:"dev/docker/production.md"};function d(r,e,l,n,p,c){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="production-docker-compose" tabindex="-1">Production (Docker Compose) <a class="header-anchor" href="#production-docker-compose" aria-label="Permalink to &quot;Production (Docker Compose)&quot;">​</a></h1><p>Выкладка production через <code>docker-compose.prod.yml</code>.</p><h2 id="типовои-сценарии" tabindex="-1">Типовой сценарий <a class="header-anchor" href="#типовои-сценарии" aria-label="Permalink to &quot;Типовой сценарий&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.prod.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod:release</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod:db-migrate</span></span></code></pre></div><h2 id="после-git-pull" tabindex="-1">После <code>git pull</code> <a class="header-anchor" href="#после-git-pull" aria-label="Permalink to &quot;После `git pull`&quot;">​</a></h2><ul><li>Если менялся код/зависимости: <code>make prod:deploy:image</code> (или <code>make prod:release</code>).</li><li>Если только фронт: <code>make prod:deploy:frontend</code>.</li><li>Если только Composer: <code>make prod:deploy:php-deps</code>.</li><li>Если только код без deps/assets: <code>make prod:deploy:code</code>.</li></ul><p>Проверка состояния: <code>make prod:doctor</code>.</p><h2 id="порты" tabindex="-1">Порты <a class="header-anchor" href="#порты" aria-label="Permalink to &quot;Порты&quot;">​</a></h2><ul><li>Внутри контейнера приложение слушает <strong>8080</strong>.</li><li>Снаружи проброс: <code>&quot;${APP_PORT:-8080}:8080&quot;</code>.</li><li>Reverb: <code>&quot;${REVERB_SERVER_PORT:-8000}:${REVERB_SERVER_PORT:-8000}&quot;</code>.</li></ul><h2 id="horizon" tabindex="-1">Horizon <a class="header-anchor" href="#horizon" aria-label="Permalink to &quot;Horizon&quot;">​</a></h2><p>В Agelto вместо <code>queue:work</code> используется <strong>Laravel Horizon</strong> (<code>horizon</code>-сервис). Перезапуск воркеров:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod:workers:restart</span></span></code></pre></div>',12)])])}const u=a(t,[["render",d]]);export{k as __pageData,u as default};
